  const parsed=IntakeRequestSchema.safeParse(JSON.parse(text));if(!parsed.success)return Response.json({error:'Check your idea and answer lengths.',safeToRetry:true},{status:400});
  claimed=true;const reply=await intakeTurn(owner,parsed.data);return Response.json({reply});
 }catch(e){const code=e instanceof Error?e.message:'';
